import unreal
mel = unreal.MaterialEditingLibrary
at = unreal.AssetToolsHelpers.get_asset_tools()
P = "/Game/Cars/M_KenneyBody"
if unreal.EditorAssetLibrary.does_asset_exist(P): unreal.EditorAssetLibrary.delete_asset(P)
m = at.create_asset("M_KenneyBody", "/Game/Cars", unreal.Material, unreal.MaterialFactoryNew())
tex = unreal.EditorAssetLibrary.load_asset("/Game/Cars/Kenney/T_Colormap")
ts = mel.create_material_expression(m, unreal.MaterialExpressionTextureSample, -900, 0); ts.set_editor_property("texture", tex)
ts.set_editor_property("sampler_source", unreal.SamplerSourceMode.SSM_WRAP_WORLD_GROUP_SETTINGS)
paint = mel.create_material_expression(m, unreal.MaterialExpressionVectorParameter, -900, 300); paint.set_editor_property("parameter_name", "Paint"); paint.set_editor_property("default_value", unreal.LinearColor(0.5, 0.5, 0.55, 1))
amt = mel.create_material_expression(m, unreal.MaterialExpressionScalarParameter, -900, 450); amt.set_editor_property("parameter_name", "PaintAmount"); amt.set_editor_property("default_value", 1.0)
fade = mel.create_material_expression(m, unreal.MaterialExpressionScalarParameter, -900, 600); fade.set_editor_property("parameter_name", "Fade"); fade.set_editor_property("default_value", 1.0)
des = mel.create_material_expression(m, unreal.MaterialExpressionDesaturation, -650, 100)
mel.connect_material_expressions(ts, "RGB", des, "")
tint = mel.create_material_expression(m, unreal.MaterialExpressionMultiply, -450, 150)
mel.connect_material_expressions(des, "", tint, "A"); mel.connect_material_expressions(paint, "", tint, "B")
boost = mel.create_material_expression(m, unreal.MaterialExpressionMultiply, -300, 150); boost.set_editor_property("const_b", 1.7)
mel.connect_material_expressions(tint, "", boost, "A")
mix = mel.create_material_expression(m, unreal.MaterialExpressionLinearInterpolate, -150, 100)
mel.connect_material_expressions(ts, "RGB", mix, "A"); mel.connect_material_expressions(boost, "", mix, "B"); mel.connect_material_expressions(amt, "", mix, "Alpha")
mel.connect_material_property(mix, "", unreal.MaterialProperty.MP_BASE_COLOR)
r = mel.create_material_expression(m, unreal.MaterialExpressionConstant, -150, 350); r.set_editor_property("r", 0.38); mel.connect_material_property(r, "", unreal.MaterialProperty.MP_ROUGHNESS)
mt = mel.create_material_expression(m, unreal.MaterialExpressionConstant, -150, 450); mt.set_editor_property("r", 0.35); mel.connect_material_property(mt, "", unreal.MaterialProperty.MP_METALLIC)
wp = mel.create_material_expression(m, unreal.MaterialExpressionWorldPosition, -900, 800)
nz = mel.create_material_expression(m, unreal.MaterialExpressionNoise, -650, 800)
nz.set_editor_property("scale", 0.45); nz.set_editor_property("quality", 1); nz.set_editor_property("levels", 1)
nz.set_editor_property("output_min", 0.0); nz.set_editor_property("output_max", 1.0); nz.set_editor_property("noise_function", unreal.NoiseFunction.NOISEFUNCTION_GRADIENT_ALU)
mel.connect_material_expressions(wp, "", nz, "Position")
c = mel.create_material_expression(m, unreal.MaterialExpressionSubtract, -450, 800); c.set_editor_property("const_b", 0.5); mel.connect_material_expressions(nz, "", c, "A")
a = mel.create_material_expression(m, unreal.MaterialExpressionMultiply, -300, 800); a.set_editor_property("const_b", 0.7); mel.connect_material_expressions(c, "", a, "A")
d = mel.create_material_expression(m, unreal.MaterialExpressionAdd, -150, 700); mel.connect_material_expressions(fade, "", d, "A"); mel.connect_material_expressions(a, "", d, "B")
mel.connect_material_property(d, "", unreal.MaterialProperty.MP_OPACITY_MASK)
m.set_editor_property("blend_mode", unreal.BlendMode.BLEND_MASKED); m.set_editor_property("two_sided", True)
mel.recompile_material(m); unreal.EditorAssetLibrary.save_loaded_asset(m)
print("KM_DONE", mel.get_num_material_expressions(m))
